mapper.sql:
WHERE s.deleted = 0
AND (s.code LIKE #{f.keyword} OR s.name LIKE #{f.keyword})
AND s.owner_user_id = #{f.ownerUserId}
AND s.org_unit_id = #{f.orgUnitId}
AND s.status = #{f.status}

AND st.to_year >= #{f.fromYear}
AND st.from_year <= #{f.toYear}

mapper.select:
SELECT k.id AS kpi_id, k.code AS kpi_code, k.name AS kpi_name, uom.name AS unit_of_measure_name, ek.year, ek.period_code, r.plan_value, r.final_result, r.completion_rate, r.score, r.rating FROM strategy_kpi sk JOIN kpi k ON k.id = sk.kpi_id LEFT JOIN unit_of_measure uom ON uom.id = k.unit_of_measure_id LEFT JOIN evaluation_result r ON r.id = ( SELECT r2.id FROM evaluation_result r2 JOIN evaluation_kpi ek2 ON ek2.id = r2.evaluation_kpi_id WHERE r2.deleted = 0 AND ek2.kpi_id = k.id AND r2.org_unit_id = #{unitId} AND ek2.year = #{year}
AND ek2.period_code = #{period} AND r2.final_result IS NOT NULL
ORDER BY FIELD(ek2.period_code, 'Q1', 'Q2', 'H1', 'Q3', 'Q4', 'Y') DESC LIMIT 1) LEFT JOIN evaluation_kpi ek ON ek.id = r.evaluation_kpi_id WHERE sk.strategy_id = #{strategyId} AND sk.objective_id = #{objectiveId} ORDER BY k.code

mapper.update:
UPDATE strategy s JOIN evaluation_stage st ON st.id = s.stage_id
SET s.status = 'HOAN_THANH', s.updated_by = 'system', s.updated_at = NOW(3), s.version = s.version + 1
WHERE s.deleted = 0 AND s.status = 'DANG_THUC_HIEN' AND st.to_year < #{year}

mapper.select:
SELECT s.id FROM strategy s JOIN evaluation_stage st ON st.id = s.stage_id
WHERE s.deleted = 0 AND s.org_unit_id = #{unitId} AND st.from_year <= #{year} AND st.to_year >= #{year}
ORDER BY s.status = 'DANG_THUC_HIEN' DESC, s.year DESC, s.id DESC LIMIT 1
